"use client"

import { motion, useInView } from "framer-motion"
import { useRef, useEffect, useState, useContext } from "react"
import { SectionHeader } from "./section-header"
import { TelemetryChart } from "./telemetry-chart"
import { AnalysisContext } from "@/app/page"

function ProgressMetric({
  label,
  value,
  index,
}: {
  label: string
  value: number
  index: number
}) {
  const ref = useRef<HTMLDivElement>(null)
  const isInView = useInView(ref, { once: true })
  const [displayValue, setDisplayValue] = useState(0)

  useEffect(() => {
    if (!isInView) return
    const duration = 1200
    const startTime = performance.now()
    function tick(now: number) {
      const elapsed = now - startTime
      const progress = Math.min(elapsed / duration, 1)
      const eased = 1 - Math.pow(1 - progress, 3)
      setDisplayValue(Math.round(value * eased))
      if (progress < 1) requestAnimationFrame(tick)
    }
    requestAnimationFrame(tick)
  }, [isInView, value])

  return (
    <motion.div
      ref={ref}
      initial={{ opacity: 0 }}
      whileInView={{ opacity: 1 }}
      viewport={{ once: true }}
      transition={{ duration: 0.4, delay: index * 0.08 }}
      className="flex flex-col gap-2"
    >
      <div className="flex items-center justify-between">
        <span className="font-mono text-[10px] tracking-[0.15em] text-muted-foreground uppercase">
          {label}
        </span>
        <span className="font-mono text-xs text-foreground tabular-nums">
          {displayValue}%
        </span>
      </div>
      <div className="h-px w-full bg-border">
        <motion.div
          className="h-px bg-foreground/50"
          initial={{ width: "0%" }}
          animate={isInView ? { width: `${value}%` } : {}}
          transition={{ duration: 1.2, ease: "easeOut", delay: index * 0.08 }}
        />
      </div>
    </motion.div>
  )
}

function MetricValue({
  label,
  value,
  unit,
  index,
}: {
  label: string
  value: string
  unit: string
  index: number
}) {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      whileInView={{ opacity: 1 }}
      viewport={{ once: true }}
      transition={{ duration: 0.4, delay: index * 0.08 }}
      className="flex flex-col gap-1"
    >
      <span className="font-mono text-[10px] tracking-[0.15em] text-muted-foreground/50 uppercase">
        {label}
      </span>
      <div className="flex items-baseline gap-1">
        <span className="font-mono text-lg font-light text-foreground tabular-nums">{value}</span>
        <span className="font-mono text-[10px] text-muted-foreground">{unit}</span>
      </div>
    </motion.div>
  )
}

export function TelemetryPanel() {
  const context = useContext(AnalysisContext)
  const analysisResult = context?.analysisResult

  const scores = analysisResult?.scores || {}
  
  // Calculate percentage values from scores
  const ssimPercent = Math.min(100, (scores.ssim_score || 0) * 100)
  const confidencePercent = Math.max(0, 100 - (scores.mean_error || 0))
  const anomalyRate = scores.anomaly_severity || 0
  const signalIntegrity = Math.max(0, 100 - (scores.difference_percentage || 0))

  if (!analysisResult) {
    return (
      <section className="relative px-6 py-32">
        <SectionHeader
          label="03"
          title="TELEMETRY"
          subtitle="Real-time performance metrics"
        />

        <div className="mx-auto flex max-w-4xl flex-col gap-16">
          {/* Placeholder content */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="rounded-lg border border-dashed border-border bg-muted/20 p-12 text-center"
          >
            <p className="font-mono text-sm text-foreground/60">
              Telemetry data will appear here after analysis completes
            </p>
          </motion.div>
        </div>
      </section>
    )
  }

  return (
    <section className="relative px-6 py-32">
      <SectionHeader
        label="03"
        title="TELEMETRY"
        subtitle="Analysis performance metrics and results"
      />

      <div className="mx-auto flex max-w-4xl flex-col gap-16">
        {/* Progress metrics */}
        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2">
          <ProgressMetric label="SSIM Score" value={Math.round(ssimPercent)} index={0} />
          <ProgressMetric label="Confidence Level" value={Math.round(confidencePercent)} index={1} />
          <ProgressMetric label="Anomaly Severity" value={Math.round(anomalyRate)} index={2} />
          <ProgressMetric label="Signal Integrity" value={Math.round(signalIntegrity)} index={3} />
        </div>

        {/* Metric values */}
        <div className="grid grid-cols-2 gap-8 sm:grid-cols-4">
          <MetricValue label="Mean Error" value={scores.mean_error?.toFixed(2) || "0"} unit="%" index={0} />
          <MetricValue label="Difference %" value={scores.difference_percentage?.toFixed(1) || "0"} unit="%" index={1} />
          <MetricValue label="Regions" value={analysisResult.regions_detected?.toString() || "0"} unit="found" index={2} />
          <MetricValue label="Mode" value={analysisResult.mode?.toUpperCase() || "N/A"} unit="" index={3} />
        </div>

        {/* Detection metrics */}
        <motion.div
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
          className="flex flex-wrap items-center justify-center gap-x-8 gap-y-3 border-t border-border pt-8"
        >
          <div className="flex items-center gap-2">
            <span className="font-mono text-[10px] tracking-wider text-muted-foreground/40 uppercase">
              Analysis ID
            </span>
            <span className="font-mono text-[9px] text-muted-foreground truncate max-w-[200px]">
              {analysisResult.analysis_id || "N/A"}
            </span>
          </div>
          <div className="flex items-center gap-2">
            <span className="font-mono text-[10px] tracking-wider text-muted-foreground/40 uppercase">
              Mode
            </span>
            <span className="font-mono text-[10px] text-muted-foreground">
              {analysisResult.mode === 'hybrid' ? 'RGB + Thermal' : 'RGB Only'}
            </span>
          </div>
          <div className="flex items-center gap-2">
            <span className="font-mono text-[10px] tracking-wider text-muted-foreground/40 uppercase">
              Status
            </span>
            <span className="font-mono text-[10px] text-foreground">
              Complete ✓
            </span>
          </div>
        </motion.div>
      </div>
    </section>
  )
}
